import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, Router, convertToParamMap, provideRouter } from '@angular/router';
import { of, throwError } from 'rxjs';
import { ApiService } from '../api.service';
import { BookingService } from '../booking.service';
import { ToastService } from '../toast.service';
import { Checkout } from './checkout';

describe('Checkout', () => {
  const toast = { show: vi.fn() };
  const api = { createReservation: vi.fn() };

  function setup() {
    sessionStorage.clear();
    toast.show.mockClear();
    api.createReservation.mockReset();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        { provide: ToastService, useValue: toast },
        { provide: ApiService, useValue: api },
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: convertToParamMap({ id: '1' }) } } },
      ],
    });
    const booking = TestBed.inject(BookingService);
    booking.start(1);
    booking.setSeats(['R7C12', 'R15C1', 'R15C2']);
    const fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
    const root: HTMLElement = fixture.nativeElement;
    const el = (id: string) => root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
    const type = (id: string, value: string) => {
      const input = el(id) as HTMLInputElement;
      input.value = value;
      input.dispatchEvent(new Event('input'));
      fixture.detectChanges();
    };
    const blur = (id: string) => {
      el(id)!.dispatchEvent(new Event('blur'));
      fixture.detectChanges();
    };
    return { fixture, root, el, type, blur, booking };
  }

  function fillValid(s: ReturnType<typeof setup>) {
    s.type('first-name-input', 'Anna');
    s.type('last-name-input', 'Kowalska');
    s.type('email-input', 'anna@example.com');
    s.type('confirm-email-input', 'anna@example.com');
    s.type('phone-input', '123456789');
    (s.el('terms-checkbox')!.querySelector('input') as HTMLInputElement).click();
    s.fixture.detectChanges();
  }

  it('shows the total and no messages initially', () => {
    const s = setup();
    expect(s.el('pay-button')!.textContent!.trim()).toBe('Pay 121.00 PLN');
    expect(s.el('first-name-error')).toBeNull();
  });

  it('validates fields after blur', () => {
    const s = setup();
    s.blur('first-name-input');
    expect(s.el('first-name-error')!.textContent).toBe('First name is required');
    s.type('first-name-input', 'A');
    expect(s.el('first-name-error')!.textContent).toBe('First name must be at least 2 characters');
    s.type('first-name-input', 'An');
    expect(s.el('first-name-error')).toBeNull();

    s.type('email-input', 'a@b');
    s.type('confirm-email-input', 'x');
    s.blur('email-input');
    s.blur('confirm-email-input');
    expect(s.el('email-error')!.textContent).toBe('Enter a valid email address');
    expect(s.el('confirm-email-error')!.textContent).toBe('Email addresses do not match');
    s.type('email-input', 'x');
    expect(s.el('confirm-email-error')).toBeNull();

    s.type('phone-input', '12345');
    s.blur('phone-input');
    expect(s.el('phone-error')!.textContent).toBe('Phone number must be exactly 9 digits');
    s.type('phone-input', '');
    expect(s.el('phone-error')).toBeNull();
  });

  it('refuses to pay an invalid form', () => {
    const s = setup();
    s.el('pay-button')!.click();
    s.fixture.detectChanges();
    expect(toast.show).toHaveBeenCalledWith('The form contains errors');
    expect(api.createReservation).not.toHaveBeenCalled();
    for (const id of ['first-name', 'last-name', 'email', 'confirm-email', 'terms']) {
      expect(s.el(`${id}-error`)).not.toBeNull();
    }
    expect(s.el('phone-error')).toBeNull();
    expect(s.el('confirm-email-error')!.textContent).toBe('Confirm email is required');
    expect(s.el('terms-error')!.textContent).toBe('You must accept the terms and conditions');
  });

  it('posts the reservation and marks the booking paid', () => {
    const s = setup();
    const navigate = vi.spyOn(TestBed.inject(Router), 'navigateByUrl').mockResolvedValue(true);
    api.createReservation.mockReturnValue(of({}));
    fillValid(s);
    s.el('pay-button')!.click();
    expect(api.createReservation).toHaveBeenCalledWith({
      screeningId: 1,
      seats: ['R7C12', 'R15C1', 'R15C2'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna@example.com', phone: '123456789' },
      totalPrice: 121,
    });
    expect(s.booking.booking()!.paid).toBe(true);
    expect(s.booking.booking()!.email).toBe('anna@example.com');
    expect(navigate).toHaveBeenCalledWith('/confirmation');
  });

  it('keeps the form and toasts when payment fails', () => {
    const s = setup();
    api.createReservation.mockReturnValue(throwError(() => new Error('boom')));
    fillValid(s);
    s.el('pay-button')!.click();
    s.fixture.detectChanges();
    expect(toast.show).toHaveBeenCalledWith('Payment failed. Please try again.');
    expect((s.el('pay-button') as HTMLButtonElement).disabled).toBe(false);
    expect(s.booking.booking()!.paid).toBe(false);
    expect(s.booking.booking()!.form.firstName).toBe('Anna');
  });
});

import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
import { BehaviorSubject, NEVER, of, throwError } from 'rxjs';
import { provideNativeDateAdapter } from '@angular/material/core';
import { ApiService } from '../api.service';
import { toIsoDate } from '../seating';
import { MovieList } from './movie-list';

describe('MovieList', () => {
  const day = (offset: number) => {
    const d = new Date();
    return toIsoDate(new Date(d.getFullYear(), d.getMonth(), d.getDate() + offset));
  };
  const movies = [
    { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' },
    { id: 2, title: 'B', genre: 'Comedy', runtimeMinutes: 90, format: 'PL subtitles' },
    { id: 3, title: 'C', genre: 'Action', runtimeMinutes: 100, format: 'PL dubbing' },
  ];
  const screenings = [
    { id: 10, movieId: 1, date: day(0), time: '20:00', occupiedSeats: [] },
    { id: 11, movieId: 1, date: day(0), time: '16:00', occupiedSeats: [] },
    { id: 12, movieId: 3, date: day(2), time: '18:00', occupiedSeats: [] },
  ];

  function setup(date: string | null, api: unknown) {
    const params = new BehaviorSubject(convertToParamMap(date ? { date } : {}));
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        provideNativeDateAdapter(),
        { provide: ApiService, useValue: api },
        { provide: ActivatedRoute, useValue: { queryParamMap: params, snapshot: { queryParamMap: params.value } } },
      ],
    });
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    const root: HTMLElement = fixture.nativeElement;
    const q = (sel: string) => Array.from(root.querySelectorAll<HTMLElement>(sel));
    return { fixture, root, q };
  }

  const okApi = { getMovies: () => of(movies), getScreenings: () => of(screenings) };

  it('shows today by default with sorted screening buttons', () => {
    const { q } = setup(null, okApi);
    const buttons = q('[data-testid=day-button]');
    expect(buttons.length).toBe(5);
    expect(buttons[0].textContent!.trim()).toBe('Today');
    expect(buttons.map((b) => b.dataset['selected'])).toEqual(['true', 'false', 'false', 'false', 'false']);
    expect(q('[data-testid=movie-card]').length).toBe(1);
    expect(q('[data-testid=screening-button]').map((b) => b.textContent!.trim())).toEqual(['16:00', '20:00']);
    expect(q('[data-testid=movie-runtime]')[0].textContent).toBe('128 min');
  });

  it('falls back to today for invalid or past dates', () => {
    for (const bad of ['garbage', day(-1), '2026-02-30']) {
      TestBed.resetTestingModule();
      const { q } = setup(bad, okApi);
      expect(q('[data-testid=day-button]')[0].dataset['selected']).toBe('true');
    }
  });

  it('selects another day, and shows the empty state', () => {
    TestBed.resetTestingModule();
    const { q, root } = setup(day(2), okApi);
    expect(q('[data-testid=day-button]')[2].dataset['selected']).toBe('true');
    expect(q('[data-testid=movie-title]').map((e) => e.textContent)).toEqual(['C']);
    TestBed.resetTestingModule();
    const far = setup(day(30), okApi);
    expect(far.q('[data-testid=day-button]').every((b) => b.dataset['selected'] === 'false')).toBe(true);
    expect(far.root.querySelector('[data-testid=movies-empty]')!.textContent).toContain('No screenings on this day');
    expect(far.q('[data-testid=movie-card]').length).toBe(0);
    expect((far.root.querySelector('[data-testid=date-picker]') as HTMLInputElement).value).not.toBe('');
    expect(root).toBeTruthy();
  });

  it('shows loading, then error with retry', () => {
    const loading = setup(null, { getMovies: () => NEVER, getScreenings: () => NEVER });
    expect(loading.q('[data-testid=movies-loading]').length).toBe(1);
    expect(loading.q('[data-testid=movie-card]').length).toBe(0);

    TestBed.resetTestingModule();
    let fail = true;
    const api = {
      getMovies: () => (fail ? throwError(() => new Error('x')) : of(movies)),
      getScreenings: () => of(screenings),
    };
    const { q, fixture } = setup(null, api);
    expect(q('[data-testid=movies-error]')[0].textContent).toContain('Failed to load movies');
    fail = false;
    q('[data-testid=movies-retry-button]')[0].click();
    fixture.detectChanges();
    expect(q('[data-testid=movie-card]').length).toBe(1);
  });
});

import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
import { of } from 'rxjs';
import { ApiService } from '../api.service';
import { BookingService } from '../booking.service';
import { ToastService } from '../toast.service';
import { SeatMap } from './seat-map';

describe('SeatMap', () => {
  const toast = { show: vi.fn() };

  function setup() {
    sessionStorage.clear();
    toast.show.mockClear();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        { provide: ToastService, useValue: toast },
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: convertToParamMap({ id: '1' }) } } },
        {
          provide: ApiService,
          useValue: {
            getScreening: () =>
              of({ id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: ['R3C7', 'R15C5', 'R1C10'] }),
            getMovie: () => of({ id: 1, title: 'T', genre: 'G', runtimeMinutes: 100, format: 'PL dubbing' }),
          },
        },
      ],
    });
    const fixture = TestBed.createComponent(SeatMap);
    fixture.detectChanges();
    const root: HTMLElement = fixture.nativeElement;
    const q = (sel: string) => Array.from(root.querySelectorAll<HTMLElement>(sel));
    const seat = (row: number, col: number) => root.querySelector<HTMLElement>(`[data-testid=seat][data-row="${row}"][data-column="${col}"]`)!;
    const couch = (row: number, start: number) => root.querySelector<HTMLElement>(`[data-testid=couch][data-row="${row}"][data-column-start="${start}"]`)!;
    const click = (el: HTMLElement) => {
      el.click();
      fixture.detectChanges();
    };
    return { fixture, root, q, seat, couch, click };
  }

  it('draws the auditorium', () => {
    const { root, q, seat, couch } = setup();
    expect(q('[data-testid=seat-row]').length).toBe(15);
    expect(q('[data-testid=seat]').length).toBe(296);
    expect(q('[data-testid=couch]').length).toBe(12);
    expect(q('[data-testid=aisle]').length).toBe(30);
    expect(q('[data-testid=row-label-left]').length).toBe(15);
    expect(q('[data-testid=row-label-right]').length).toBe(15);
    expect(root.querySelector('[data-testid=seat-map-subtitle]')!.textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
    expect(root.querySelector('[data-testid=seat][data-row="1"][data-column="4"]')).toBeNull();
    expect(root.querySelector('[data-testid=seat][data-row="11"][data-column="1"]')).not.toBeNull();
    expect(seat(3, 7).dataset['state']).toBe('unavailable');
    expect(seat(1, 10).dataset['state']).toBe('unavailable');
    expect(seat(1, 11).dataset['state']).toBe('accessible');
    expect(seat(2, 5).dataset['state']).toBe('available');
    expect(couch(15, 5).dataset['state']).toBe('unavailable');
    expect(q('[data-testid=seat-row][data-row="15"] [data-testid=seat]').length).toBe(0);
    expect(seat(1, 5).textContent).toBe('5');
  });

  it('selects, deselects and limits seats', () => {
    const { root, q, seat, couch, click } = setup();
    const count = () => root.querySelector('[data-testid=selected-seats-count]')!.textContent;
    click(seat(7, 12));
    click(seat(7, 11));
    click(couch(15, 1));
    expect(seat(7, 12).dataset['state']).toBe('selected');
    expect(couch(15, 1).dataset['state']).toBe('selected');
    expect(count()).toBe('Selected seats: 4');
    expect(q('[data-testid=selected-seats-row]').map((e) => e.textContent)).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);

    click(seat(3, 7));
    expect(count()).toBe('Selected seats: 4');

    for (const c of [5, 6, 7]) click(seat(2, c));
    expect(count()).toBe('Selected seats: 7');
    click(couch(15, 3));
    expect(count()).toBe('Selected seats: 9');
    click(seat(2, 8));
    expect(count()).toBe('Selected seats: 10');
    click(seat(2, 9));
    expect(count()).toBe('Selected seats: 10');
    expect(toast.show).toHaveBeenCalledWith('Maximum 10 seats per booking');
    click(couch(15, 3));
    click(seat(2, 8));
    expect(count()).toBe('Selected seats: 7');
    click(seat(7, 12));
    expect(seat(7, 12).dataset['state']).toBe('available');
    expect(TestBed.inject(BookingService).booking()!.seats).toContain('R15C1');
  });
});
